        // Toggle Nutrient Layer Heatmap Overlay on Comprehensive Map
        function toggleNutrientLayerComp(layerValue) {
            // Hide all legends
            document.querySelectorAll('#page-comprehensive .nutrient-legend-box').forEach(el => el.style.display = 'none');
            
            // Clean old raster overlay
            if (compRasterOverlay) {
                mapComp.removeLayer(compRasterOverlay);
                compRasterOverlay = null;
            }
            
            if (layerValue === "OFF") {
                // Revert to boundary colors
                if (compBoundaryLayer) {
                    compBoundaryLayer.setStyle({ color: "#ff7800", fillColor: "#ff7800", fillOpacity: 0.15 });
                }
            } else {
                // Show selected legend box
                let legendBox = document.getElementById(`${layerValue.toLowerCase()}-comp-legend`);
                if (legendBox) legendBox.style.display = 'block';
                
                // Make block boundaries outline-only (transparent fill) so raster underneath is visible
                if (compBoundaryLayer) {
                    compBoundaryLayer.setStyle({ color: "#ff7800", fillColor: "#ff7800", fillOpacity: 0.0 });
                }
                
                // Add the authentic GeoTIFF raster overlay
                if (typeof RASTER_OVERLAYS !== 'undefined' && RASTER_OVERLAYS[layerValue]) {
                    let oData = RASTER_OVERLAYS[layerValue];
                    compRasterOverlay = L.imageOverlay(oData.dataUrl, oData.bounds, { opacity: 0.85, zIndex: 400 }).addTo(mapComp);
                }
            }
        }

