        // Page Deck Switcher Router (Fail-Proof & Error Safe)
                function switchPage(pageId) {
            console.log("Navigating to:", pageId);
            const target = document.getElementById(pageId);
            if (!target) {
                console.error("Page not found:", pageId);
                return;
            }
            
            // Hide all pages
            const pages = document.querySelectorAll('.page-container');
            pages.forEach(p => {
                p.classList.remove('active');
                p.style.display = 'none';
            });
            
            // Show target page
            target.classList.add('active');
            target.style.display = 'flex';
            window.scrollTo(0, 0);
            
            // Resize maps if needed
            setTimeout(function() {
                try {
                    if (typeof mapComp !== 'undefined' && mapComp && typeof mapComp.invalidateSize === 'function') {
                        mapComp.invalidateSize();
                    }
                    if (typeof mapStd !== 'undefined' && mapStd && typeof mapStd.invalidateSize === 'function') {
                        mapStd.invalidateSize();
                    }
                } catch(e) {
                    console.log("Map resize notice:", e);
                }
            }, 100);
        }

